"""Version and build provenance, stamped on every report ("Generated by Magen")."""

from __future__ import annotations

import os
import shutil
import subprocess
from functools import lru_cache
from pathlib import Path

from app import __version__


@lru_cache(maxsize=1)
def commit_hash() -> str:
    """Return the short git commit hash, or ``MAGEN_COMMIT``, or ``"unknown"``.

    Packaged builds have no git checkout; CI stamps ``MAGEN_COMMIT`` at build time.
    """
    env = os.environ.get("MAGEN_COMMIT")
    if env:
        return env
    git = shutil.which("git")
    if git is None:
        return "unknown"
    try:
        out = subprocess.run(  # noqa: S603 - fixed argv, no shell, no user input
            [git, "rev-parse", "--short=12", "HEAD"],
            cwd=Path(__file__).resolve().parent,
            capture_output=True,
            text=True,
            timeout=2,
            check=True,
        )
    except (OSError, subprocess.SubprocessError):
        return "unknown"
    return out.stdout.strip() or "unknown"


def generated_by() -> str:
    """Header line used in reports and exports."""
    return f"Generated by Magen {__version__} ({commit_hash()})"
